css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; left: 24%; width: 52%; height: 15%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); box-shadow: inset 0 0 0 1px color-mix(in srgb, #000 18%, transparent); animation: jenga-settle calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader span:nth-of-type(1) { bottom: 4%; }
.loader span:nth-of-type(2) { bottom: 22%; }
.loader span:nth-of-type(3) { bottom: 40%; }
.loader span:nth-of-type(4) { bottom: 58%; }
.loader span:nth-of-type(5) { bottom: 76%; }
.loader .pull { position: absolute; left: 24%; bottom: 40%; width: 52%; height: 15%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #fff 30%, var(--accent-2)), var(--accent-2)); box-shadow: 0 3px 8px color-mix(in srgb, #000 30%, transparent); animation: jenga-move calc(var(--loader-speed) * 3) cubic-bezier(.5, 0, .3, 1) infinite; }
@keyframes jenga-move { 0%, 8% { transform: translate(0, 0); } 30% { transform: translate(44%, 0); } 56% { transform: translate(44%, -300%); } 80%, 100% { transform: translate(0, -300%); } }
@keyframes jenga-settle { 0%, 52% { transform: translateY(0) rotate(0deg); } 62% { transform: translateY(2%) rotate(-.8deg); } 76%, 100% { transform: translateY(0) rotate(0deg); } }
